func (s CustomDiveStruct) JSONSize() int {
	size := 59
	size += len(s.Lookup) * 24
	for k := range s.Lookup {
		size += len(k) * 2
	}
	size += len(s.Mixed) * 24
	for k := range s.Mixed {
		size += len(k) * 2
	}
	if s.Ptr == nil {
		size += 4
	} else {
		size += 20
	}
	if n := len(s.Tags); n > 0 {
		size += n - 1
	}
	for i0 := range s.Tags {
		size += len(s.Tags[i0])*2 + 2
	}
	if n := len(s.Trim); n > 0 {
		size += n - 1
	}
	for i0 := range s.Trim {
		size += len(s.Trim[i0])*2 + 2
	}
	return size
}

